def _wire(value):
    return json.dumps(value, ensure_ascii=True, sort_keys=True, separators=(",", ":"), allow_nan=False).encode("ascii")


def _digest(raw):
    return sha256(raw).hexdigest()


def example(tmp_path):
    root = tmp_path / "runs"
    root.mkdir()
    run = root / ("b" * 32)
    run.mkdir()
    report = json.loads(_REPORT_JSON)
    base = b"{}"
    report["native_files"] = [[name, _digest(base)] for name, _ in report["native_files"]]
    for _ in range(10):
        size = len(_wire(report))
        if report["result_bytes"] == size:
            break
        report["result_bytes"] = size
    installation = {"report_schema": report["schema"], "basefiles": {
        name: {"sha256": _digest(base)} for name, _ in report["native_files"]}}
    install_bytes = _wire(installation)
    for folder in ("basefiles", "session-basefiles"):
        (run / folder).mkdir()
        for name, _ in report["native_files"]:
            (run / folder / (name + ".json")).write_bytes(base)
    session = {"config": {"strategy_id": "synthetic"}, "policy": {}, "fee_reserve_cny": "0", "fee_source": "synthetic"}
    request = {"schema": "nsh-run-v1", "run_id": run.name, "installation_sha256": _digest(install_bytes),
               "report_schema": report["schema"], "session": session, "session_sha256": _digest(_wire(session)),
               "backtest": {"start": 202401030930, "end": 202401091500, "name": "configured"}}
    request_bytes = _wire(request)
    (run / "outputs").mkdir()
    native = b"synthetic-original-wt-output\n"
    (run / "outputs/test.trades.csv").write_bytes(native)
    result = {"schema": "nsh-run-v1", "run_id": run.name, "request_sha256": _digest(request_bytes),
              "installation_sha256": _digest(install_bytes), "report_schema": report["schema"], "report": report,
              "native_outputs": {"outputs/test.trades.csv": _digest(native)}}
    for name, raw in (("request.json", request_bytes), ("installation.json", install_bytes), ("result.json", _wire(result))):
        (run / name).write_bytes(raw)
    fact = HostResult(run.name, "completed", "complete", _digest(request_bytes), _digest(install_bytes),
                      str(run), _wire(report).decode("ascii"), 123, 0, False, True, True, 42)
    config = {"label": "合成样本", "name": "configured", "start": 202401030930, "end": 202401091500,
              "session_sha256": _digest(_wire(session)), "max_seconds": 5}
    return root, run, fact, config, report


def publish(archive, fact, config, report, deadline=None):
    return archive.publish(fact, "a" * 32, "1" * 32, config, _digest(_wire(report)), len(report["records"]),
                           monotonic() + 5 if deadline is None else deadline)
